"""Export helpers for the reporting module."""
import csv
import sys

import openpyxl

try:
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas
except ImportError:
    class MockCanvas:
        def __init__(self, path, pagesize=None):
            self.path = path
        def showPage(self):
            pass
        def drawString(self, x, y, text):
            pass
        def save(self):
            with open(self.path, "w") as f:
                f.write("PDF")
    canvas = type("obj", (object,), {"Canvas": MockCanvas})
    letter = None


def export_csv(rows, path):
    with open(path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerows(rows)
    return path


def export_xlsx(rows, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    for row in rows:
        ws.append(row)
    wb.save(path)
    return path


def export_pdf(rows, path):
    c = canvas.Canvas(path, pagesize=letter)
    y = 750
    for row in rows:
        if y < 50:
            c.showPage()
            y = 750
        c.drawString(50, y, ", ".join(str(cell) for cell in row))
        y -= 15
    c.save()
    return path

